def prepare():
    assert not (BASE/'review.json').exists()
    tree=read(RAW/'exec25_agena_tree.json');assert not tree['truncated'] and len(tree['tree'])==829
    revision='54115453b0c8d500fa45bdffaeaf728c825391d3';assert tree['sha']==revision
    commit=read(RAW/'exec25_agena_cutoff_commits.json')[0];assert commit['sha']==revision and commit['commit']['committer']['date']=='2026-09-01T23:23:51Z'
    nodes={x['path']:x for x in tree['tree'] if x['type']=='blob'};originals=[]
    for name in ['agena-source-map.json','agena-cli-map.json']:
        manifest=read(ACQ/name);assert manifest['revision']==revision
        for entry in manifest['files']:
            request=entry['request'];path=RAW/(request['id']+'.'+request['extension']);data=path.read_bytes()
            blob=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
            assert blob==entry['git_blob_sha1']==nodes[entry['path']]['sha']
            receipt=read(RAW/(request['id']+'.receipt.json'));assert receipt['status']=='saved' and receipt['url']==request['url'] and receipt['sha256']==hashlib.sha256(data).hexdigest()
            originals.append(dict(path=entry['path'],git_blob_sha1=blob,local_copy=ref(path,'Exact pinned original'),receipt=ref(RAW/(request['id']+'.receipt.json'),'Bounded original acquisition')))
    assert len(originals)==16
    write(BASE/'git-byte-validation.json',dict(status='pass',revision=revision,date=commit['commit']['committer']['date'],originals=originals,evidence=[ref(RAW/'exec25_agena_tree.json','Complete pinned tree'),ref(RAW/'exec25_agena_cutoff_commits.json','Cutoff-limited revision query')],native_execution=False))
    findings=[
      ('exec25_agena_src_00.txt',['This repository is frozen','final release here is **1.042**','requires a valid license key','headless'], 'README identifies frozen public wrapper,private continuation,source/usage distinction and deployment conditions.'),
      ('exec25_agena_src_02.txt',['1.043-SNAPSHOT','master-SNAPSHOT','0.0.19','download-maven-plugin','<phase>clean</phase>'], 'Maven project/core/learning/native resource identities are separate;the core snapshot and downloaded product resources are not an immutable environment.'),
      ('exec25_agena_src_09.txt',['public void setObservation(Node node, Object value)','addHardEvidenceObservation','public void setObservationSoft'], 'Selected methods add scenario evidence with model/state/type validation;selected path does not implement mechanism replacement.'),
      ('exec25_agena_src_06.txt',['propagateDDAlgorithm','KEEP_TAILS_ZERO_REGIONS','CALCULATE_LOGPE','finally {','InconsistentEvidenceException','OutOfMemoryException'], 'Selected calculation delegates to core,maps flags,restores modified message settings and separates resource/inconsistent-evidence/general failures;native core behavior unqualified.'),
      ('exec25_agena_cli_00.txt',['calculatedIds.contains(dataSet.getId())','getString("id")','StandardOpenOption.TRUNCATE_EXISTING','System.exit(1)','System.exit(3)'], 'Selected cache uses dataset identifiers;selected write rewrites accumulated output;source alone establishes neither full cache identity nor atomic recovery.'),
      ('exec25_agena_cli_01.txt',['longOpt("model")','longOpt("data")','longOpt("use-cache")','System.exit(2)'], 'Calculator launcher has model/data/output/cache options and setup-error exit;no MCP contract inferred.'),
      ('exec25_agena_cli_02.txt',['StructureLearner learner = new StructureLearner()','learner.executeJson(config)','Concurrency.applyThreadCount','releaseEngineThreads'], 'Learning launcher delegates algorithms/configuration and exposes thread controls;does not establish hidden-confounding/dependent-data validity.')
    ]
    checked=[]
    for filename,tokens,finding in findings:
        text=(RAW/filename).read_text();assert all(t in text for t in tokens),filename
        checked.append(dict(finding=finding,source=ref(RAW/filename,'Inspected primary implementation'),anchors=tokens))
    license_text=(ACQ/'agena-license.txt').read_text()
    for token in ['16 July 2025','Version 2.4','2.5 Restrictions','accessible via a network']:assert token in license_text,token
    checked.append(dict(finding='Retained commercial usage document version2.4,updated16July2025,has embedding/network-service restrictions in section2.5;scope-specific entitlement remains unresolved.',source=ref(RAW/'exec25_agena_src_05.pdf','Original agreement pages1,4-5;section2.5'),text=ref(ACQ/'agena-license.txt','Extracted original text,not substitute original')))
    write(BASE/'primary-review.json',dict(status='pass_for_selected_sources',findings=checked,evidence=[ref(BASE/'git-byte-validation.json','Sixteen authenticated originals'),ref(RAW/'exec25_agena_src_01.txt','Original Apache source notice')],native_execution=False))
    write(BASE/'exact-results.json',exact.calculate())
    write(BASE/'mathematical-review.json',dict(status='pass_for_exact_authored_examples',evidence=[ref(Path(exact.__file__),'Independent fraction enumeration'),ref(BASE/'exact-results.json','Reproducible generated witnesses')],findings=['Finite confounded law yields observed3/5 contrast and zero intervention contrast.','Changed model/data with same scenario identifier requires invalidation;stipulated stale error3/5.','8000/200=40;8000/160=50;8000/100=80USD;not measured prices.'],native_execution=False))
    revisit='Select a named permitted immutable runtime,core/native/learning artifacts and deployment agreement;inspect delegate semantics and private-release maintenance;implement full query/cache/failure contracts and preregister matched public oracles before native integration.'
    choices=[dict(candidate='Public AgenaRisk Java API wrapper',revision=revision,decision='reference',integration_allowed=False),dict(candidate='Licensed core and deployment profile',decision='conditional_integration_not_approved',reason='Mutable core snapshot and profile-specific entitlement/native qualification unresolved',integration_allowed=False),dict(candidate='Private successor API',decision='defer',reason='No inspected immutable runtime or technical/maintenance evidence',integration_allowed=False)]
    value=dict(operation=OP,candidate='AgenaRisk',decision='reference',canonical_candidates=choices,outcome='pass',scope='Bounded reference decision only',alternatives=[dict(route=a,disposition=b,reason=c) for a,b,c in [('adopt','defer','Complete causal/runtime/rights contract not qualified'),('integrate','conditional',revisit),('port','published_source_only_conditional','Source notice does not permit porting proprietary core;dependencies and semantic tests required'),('reference','retain','Concrete original wrapper,CLI,rights and scientific comparators'),('reject','semantic_shortcuts','Observation is not mechanism replacement;scenario ID is not full request identity')]],owners=[dict(role=a,responsibility=b) for a,b in [('Scientific','Assumptions,estimand and evidence/intervention distinction'),('Interface','Versioned schemas,cache identity and typed outcomes'),('Platform','Process isolation,deadlines,recovery and resource budgets'),('Rights','Permitted deployment profile and complete artifacts'),('Evaluation/maintenance','Matched public oracles,all-attempt costs and private-release transition')]],owner_status='Proposed roles;no institutional acceptance',costs=dict(actual_quote='Unknown',measured=False,illustration=ref(BASE/'exact-results.json','Hypothetical complete costs')),maintenance='Frozen public repository;private successor uninspected',revisit_trigger=revisit,integration_allowed=False,capabilities=[],limitations=LIMITS)
    write(BASE/'choice.json',value)
    write(BASE/'conversion-contract.json',dict(status='proposed_reference_only',inputs=['request_attempt_id','question_estimand_restrictions','graph_parameters_states','observations_vs_interventions','model_data_schema_digests','wrapper_core_delegate_versions','flags_deadline_budget','rights_profile'],outputs=['identified_conditional_refusal','typed_execution_status','all_requested_scenarios','model_data_query_bound_cache','durable_output_digest','all_attempt_costs'],refusals=['Unjustified intervention interpretation','Unknown runtime/rights','Stale cache identity','Unsupported graph/target','Inconsistent evidence','Resource exhaustion','Unknown completion','Incomplete output'],integration_allowed=False))
    fixtures=['finite_observational_vs_interventional_law','state_identifier_permutation','impossible_evidence','tail_flags','changed_model_same_scenario_id','changed_data_same_scenario_id','duplicate_request','interrupted_output_rewrite','resource_refusal','cancellation','concurrent_model_calls','missing_result_object','learning_delegate_graph_and_effect_oracle']
    write(BASE/'qualification-plan.json',dict(status='proposed_not_executed',arms=['Exact finite-network reference','Permitted pinned commercial runtime','Proposed typed adapter'],fixtures=[dict(name=n,status='not_run') for n in fixtures],freezes=['Scientific question/assumptions/truth','Exact wrapper,core,native and learning artifacts','Deployment rights','Data split and numeric settings','Scientific and failure oracle','Complete request,attempt,completion and cost denominators'],data='Generated structural laws for known truth;permitted public data for workflow realism',native_execution=False))
    write(BASE/'dependency-license-review.json',dict(status='reference_scope_only',published_source='Retained Apache2.0 notice',usage='README valid-key requirement;retained16July2025agreement version2.4section2.5',project='1.043-SNAPSHOT',public_release_label='1.042',core='master-SNAPSHOT',learning='0.0.19',unknown=['Immutable core/native dependencies','Applicable enterprise/service agreement','Private-release support','Actual quote'],agreement_accepted=False,integration_allowed=False,evidence=[ref(BASE/'primary-review.json','Authentic source and usage distinctions')]))
    write(BASE/'omissions-register.json',dict(global_blocker=False,known_routes=[revisit],unresolved=['Complete native/runtime identity and rights','Current private successor','Delegate algorithms and scientific assumptions','Actual prices and supported concurrency'],unknown_without_information=['Bank assignment truth','Causal validity beyond admitted restrictions','Actual business value'],next_action=revisit))
    source=dict(integrated_citation_key='exec25_agena_source',kind='software_primary_sources',title='AgenaRisk pinned public Java wrapper,CLI and licensed runtime boundaries',author='AgenaRisk contributors',year=2026,source_identity='https://github.com/AgenaRisk/api/tree/'+revision,version_date=revision+';1September2026;acquired25October2026;cutoff7October2026',local_copy=ref(RAW/'exec25_agena_src_00.txt','Original freeze and wrapper identity'),local_sources=[x['local_copy'] for x in originals],inspected_anchors=checked,supported_claims=[x['finding'] for x in checked],evidence=[ref(BASE/'git-byte-validation.json','Original byte identity'),ref(BASE/'primary-review.json','Inspected anchors and bounded claims')],limitations=LIMITS)
    authored=dict(integrated_citation_key='exec25_agena_choice',kind='project_evidence_not_scholarly_paper',title='AgenaRisk reference choice with evidence/intervention,cache and failure contracts',author='Causal banking proposal project',year=2026,source_identity=str(BASE.relative_to(ROOT)),version_date='25October2026;proposal only;no native execution',local_copy=ref(BASE/'choice.json','Bounded reference decision'),inspected_anchors=[ref(BASE/n,'Authored analysis') for n in ['mathematical-review.json','conversion-contract.json','dependency-license-review.json','qualification-plan.json','omissions-register.json']],supported_claims=['Exact finite confounding/cache/cost witnesses','Conditional integration and rights-specific alternatives','Public native qualification remains proposed'],limitations=LIMITS)
    write(BASE/'source-audit.json',dict(sources=[source,authored],new_records=2,new_scholarly_pdfs=0,native_execution=False))
    write(BASE/'plan-review.json',dict(status='pass_for_bounded_reference',evidence=[ref(BASE/n,'Reviewed plan and evidence') for n in ['plan.md','primary-review.json','choice.json','mathematical-review.json','conversion-contract.json','dependency-license-review.json','qualification-plan.json']],findings=['Concrete wrapper and licensed/private candidates separated','No umbrella integration permission','Source paths distinguished from native execution','Public evaluation and complete costs defined;other ready work remains eligible']))
    write(BASE/'copyedit-review.json',dict(status='pass_for_connected_argument',evidence=[ref(BASE/'development.tex','Connected banking and technical argument'),ref(BASE/'sponsor-addition.md','Investment implications')],findings=['Source version distinctions and immutable tree explicit','Conditional source findings separated from independent witnesses','Coverage,native,rights,visual and final gates retained'],visual_acceptance=False))
    review=dict(status='pass_for_bounded_reference_only',reviewer=dict(name='Codex author/coordinator',kind='author'),evidence=[ref(BASE/n,'Reviewed source decision') for n in ['primary-review.json','git-byte-validation.json','choice.json','mathematical-review.json','exact-results.json','source-audit.json','conversion-contract.json','dependency-license-review.json','qualification-plan.json','omissions-register.json','plan-review.json','copyedit-review.json','development.tex','sponsor-addition.md']]+[ref(Path(__file__),'Reviewed decision logic')],findings=['Sixteen authentic originals inspected','Reference choice grants no native capability or licensed deployment right','Independent exact examples reproduced'],limitations=LIMITS,integration_allowed=False)
    verify_bindings(review);write(BASE/'review.json',review);print(json.dumps(dict(review='pass_for_reference_only',originals=16,new_records=2,native_execution=False)))

def receipt():
    state=core.read(ROOT,core.STATE);assert state['execution_runtime']['active']['operation']==OP
    verify_bindings(read(BASE/'review.json'));graph,merged,_=run.combined(ROOT,state);node=run.ledger.operation(graph,OP)
    value=read(BASE/'choice.json');value.update(status='pass',evidence=[ref(BASE/'review.json','Bounded source/decision review')]);output=ROOT/node['outputs'][0];write(output,value)
    evidence=[ref(BASE/n,'Reviewed reference disposition') for n in ['review.json','choice.json','conversion-contract.json','dependency-license-review.json','qualification-plan.json']]
    findings=['Pinned wrapper,source/usage notices,mutable dependencies and maintenance transition bound','Scientific/target/failure semantics,alternatives,owners,costs and revisit trigger explicit','Integration remains disallowed;permitted complete runtime and native oracles required']
    result=run.ledger.receipt_template(node);result.update(outcome='pass',execution='performed',scope='Public wrapper reference decision;no runtime qualification',reviewer=dict(name='Codex author/coordinator',kind='author'),outputs=[ref(output,'Reference disposition')],criteria=[dict(index=i,verdict='pass',finding=f,evidence=evidence) for i,f in enumerate(findings)],limitations=LIMITS,capabilities=[],nonexecution_reason='',revisit_trigger=value['revisit_trigger'])
    run.validate_receipt(ROOT,merged,node,result,len(state['execution_program']['turns']));verify_bindings(result);write(BASE/'operation-receipt.json',result);print('AgenaRisk bounded reference receipt prepared.')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('command',choices=['prepare','receipt']);a=p.parse_args();prepare() if a.command=='prepare' else receipt()
